

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .chat_completion_message_tool_calls import ChatCompletionMessageToolCalls
from .chat_completion_response_message_function_call import ChatCompletionResponseMessageFunctionCall
from .chat_completion_response_message_role import ChatCompletionResponseMessageRole


class ChatCompletionResponseMessage(UniversalBaseModel):
    """
    A chat completion message generated by the model.
    """

    content: typing.Optional[str] = pydantic.Field(default=None)
    """
    The contents of the message.
    """

    tool_calls: typing.Optional[ChatCompletionMessageToolCalls] = None
    role: ChatCompletionResponseMessageRole = pydantic.Field()
    """
    The role of the author of this message.
    """

    function_call: typing.Optional[ChatCompletionResponseMessageFunctionCall] = pydantic.Field(default=None)
    """
    Deprecated and replaced by `tool_calls`. The name and arguments of a function that should be called, as generated by the model.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
